import org.apache.lucene.geo.XYCircle;
import org.apache.lucene.geo.XYPoint;
import org.apache.lucene.geo.XYRectangle;

import java.util.Random;

public class Verify {
  static int failures = 0;

  static void check(boolean cond, String msg) {
    if (!cond) {
      failures++;
      System.out.println("FAIL: " + msg);
    }
  }

  public static void main(String[] args) {
    // 1. XYPoint: -0.0 vs 0.0 must be unequal (Float.compare semantics), hashCode consistent
    XYPoint p0 = new XYPoint(0.0f, 0.0f);
    XYPoint pn = new XYPoint(-0.0f, -0.0f);
    check(!p0.equals(pn), "XYPoint(0,0).equals(XYPoint(-0,-0)) should be false");
    check(!pn.equals(p0), "XYPoint(-0,-0).equals(XYPoint(0,0)) should be false");
    XYPoint p0c = new XYPoint(0.0f, 0.0f);
    XYPoint pnc = new XYPoint(-0.0f, -0.0f);
    check(p0.equals(p0c) && p0.hashCode() == p0c.hashCode(), "XYPoint(0,0) copy equals/hashCode");
    check(pn.equals(pnc) && pn.hashCode() == pnc.hashCode(), "XYPoint(-0,-0) copy equals/hashCode");

    // 2. XYPoint: symmetric mixed zero case
    XYPoint mixed1 = new XYPoint(0.0f, -0.0f);
    XYPoint mixed2 = new XYPoint(-0.0f, 0.0f);
    check(!mixed1.equals(mixed2), "mixed zero points should not be equal");
    check(!mixed1.equals(new Object()), "XYPoint vs other type");
    check(!mixed1.equals(null), "XYPoint vs null");

    // 3. XYPoint: random floats, equals<=>hashCode contract vs Float.compare
    Random r = new Random(42);
    for (int i = 0; i < 2_000_000; i++) {
      float x1 = randomFloatish(r), y1 = randomFloatish(r);
      float x2 = randomFloatish(r), y2 = randomFloatish(r);
      XYPoint a = new XYPoint(x1, y1);
      XYPoint b = new XYPoint(x2, y2);
      boolean cmp = Float.compare(x1, x2) == 0 && Float.compare(y1, y2) == 0;
      boolean eq = a.equals(b);
      check(eq == cmp, "XYPoint.equals mismatch for (" + x1 + "," + y1 + ") vs (" + x2 + "," + y2 + ")");
      if (eq) {
        check(a.hashCode() == b.hashCode(), "hashCode mismatch for equal points");
      }
    }

    // 4. XYCircle: -0.0 vs 0.0 for x, y, radius
    XYCircle c0 = new XYCircle(0.0f, 0.0f, 1.0f);
    XYCircle cn = new XYCircle(-0.0f, -0.0f, 1.0f);
    check(!c0.equals(cn), "XYCircle zeros should not be equal");
    XYCircle cr0 = new XYCircle(1.0f, 1.0f, 0.0f);
    XYCircle crn = new XYCircle(1.0f, 1.0f, -0.0f);
    check(!cr0.equals(crn), "XYCircle radius -0.0 vs 0.0 should not be equal");
    XYCircle cc = new XYCircle(0.0f, 0.0f, 1.0f);
    check(c0.equals(cc) && c0.hashCode() == cc.hashCode(), "XYCircle copy equals/hashCode");
    XYCircle crc = new XYCircle(1.0f, 1.0f, 0.0f);
    check(cr0.equals(crc) && cr0.hashCode() == crc.hashCode(), "XYCircle radius copy equals/hashCode");

    // 5. XYCircle: random contract
    for (int i = 0; i < 1_000_000; i++) {
      float x1 = randomFloatish(r), y1 = randomFloatish(r), rad1 = Math.abs(randomFloatish(r)) % 100 + 0.1f;
      float x2 = randomFloatish(r), y2 = randomFloatish(r), rad2 = Math.abs(randomFloatish(r)) % 100 + 0.1f;
      XYCircle a = new XYCircle(x1, y1, rad1);
      XYCircle b = new XYCircle(x2, y2, rad2);
      boolean cmp = Float.compare(x1, x2) == 0 && Float.compare(y1, y2) == 0 && Float.compare(rad1, rad2) == 0;
      boolean eq = a.equals(b);
      check(eq == cmp, "XYCircle.equals mismatch for (" + x1 + "," + y1 + "," + rad1 + ") vs (" + x2 + "," + y2 + "," + rad2 + ")");
      if (eq) {
        check(a.hashCode() == b.hashCode(), "XYCircle hashCode mismatch");
      }
    }

    // 6. XYRectangle: -0.0 vs 0.0 corners
    XYRectangle r0 = new XYRectangle(0.0f, 1.0f, 0.0f, 1.0f);
    XYRectangle rn = new XYRectangle(-0.0f, 1.0f, -0.0f, 1.0f);
    check(!r0.equals(rn), "XYRectangle zeros should not be equal");
    XYRectangle rc = new XYRectangle(-0.0f, 1.0f, -0.0f, 1.0f);
    XYRectangle rnc = new XYRectangle(-0.0f, 1.0f, -0.0f, 1.0f);
    check(rc.equals(rnc) && rc.hashCode() == rnc.hashCode(), "XYRectangle copy equals/hashCode");

    // 7. XYRectangle: random contract
    for (int i = 0; i < 1_000_000; i++) {
      float minX1 = randomFloatish(r), maxX1 = minX1 + Math.abs(r.nextFloat()) % 10;
      float minY1 = randomFloatish(r), maxY1 = minY1 + Math.abs(r.nextFloat()) % 10;
      float minX2 = randomFloatish(r), maxX2 = minX2 + Math.abs(r.nextFloat()) % 10;
      float minY2 = randomFloatish(r), maxY2 = minY2 + Math.abs(r.nextFloat()) % 10;
      XYRectangle a = new XYRectangle(minX1, maxX1, minY1, maxY1);
      XYRectangle b = new XYRectangle(minX2, maxX2, minY2, maxY2);
      boolean cmp = Float.compare(minX1, minX2) == 0 && Float.compare(maxX1, maxX2) == 0
          && Float.compare(minY1, minY2) == 0 && Float.compare(maxY1, maxY2) == 0;
      boolean eq = a.equals(b);
      check(eq == cmp, "XYRectangle.equals mismatch");
      if (eq) {
        check(a.hashCode() == b.hashCode(), "XYRectangle hashCode mismatch");
      }
    }

    if (failures == 0) {
      System.out.println("ALL CHECKS PASSED");
    } else {
      System.out.println(failures + " FAILURES");
      System.exit(1);
    }
  }

  // biased toward zero and small values to hit +/-0.0 frequently
  static float randomFloatish(Random r) {
    int mode = r.nextInt(4);
    switch (mode) {
      case 0:
        return r.nextBoolean() ? 0.0f : -0.0f;
      case 1:
        return (r.nextBoolean() ? 1 : -1) * r.nextFloat() * 10;
      case 2:
        return (float) Math.floor(r.nextFloat() * 1000) / 4;
      default:
        return r.nextFloat();
    }
  }
}

